-- Retire current guild configuration/access; retain historical battles and audit records.
UPDATE pb_discord_settings SET guild_catalog=COALESCE((SELECT jsonb_agg(g) FROM jsonb_array_elements(CASE WHEN jsonb_typeof(guild_catalog)='array' THEN guild_catalog ELSE '[]'::jsonb END) g WHERE upper(trim(g->>'tag'))<>'YIP'),'[]'::jsonb) WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(guild_catalog)='array' THEN guild_catalog ELSE '[]'::jsonb END) g WHERE upper(trim(g->>'tag'))='YIP');
UPDATE wosb_diplomacy SET data=jsonb_set(jsonb_set(data,'{memberships}',COALESCE((SELECT jsonb_agg(m) FROM jsonb_array_elements(data->'memberships') m WHERE upper(m->>'guildTag')<>'YIP'),'[]'::jsonb)),'{relations}',COALESCE((SELECT jsonb_agg(r) FROM jsonb_array_elements(data->'relations') r WHERE upper(r->>'from')<>'GUILD:YIP' AND upper(r->>'to')<>'GUILD:YIP'),'[]'::jsonb)),revision=revision+1,updated_at=now() WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(data->'memberships') m WHERE upper(m->>'guildTag')='YIP') OR EXISTS(SELECT 1 FROM jsonb_array_elements(data->'relations') r WHERE upper(r->>'from')='GUILD:YIP' OR upper(r->>'to')='GUILD:YIP');
